#!/usr/bin/env node
// Regenerates tigergraph/loading_job.gsql from load/common.mjs so the TSV
// column order and the LOAD statements can never drift apart.
//   node tigergraph/load/gen-loading-job.mjs > tigergraph/loading_job.gsql

import { COMMON, VERTEX_TYPES, EDGE_TYPES } from './common.mjs';

const L = [];
L.push(`/*
 * GENERATED by tigergraph/load/gen-loading-job.mjs - edit common.mjs, not this file.
 *
 * Loading job for the TSV files written by load/export-to-csv.mjs.
 * Every vertex file has a header row; columns are referenced by name.
 * wcc_id / community_id are left at their defaults ("_"): GDS writes them.
 *
 * Edge types with several FROM/TO pairs get one LOAD line per pair, selected
 * with a WHERE filter on the from_type / to_type columns, and the vertex type
 * written after the id expression ($"from_id" Report) as GSQL requires for
 * multi-pair edge types.
 *
 * Run (GSQL shell on the server, files on the server's disk):
 *   RUN LOADING JOB load_jaal USING v_Phone="/path/out/v_Phone.tsv", ...
 * or from a client with pyTigerGraph / REST:
 *   POST /restpp/ddl/JAAL?tag=load_jaal&filename=v_Phone&sep=%09&eol=%0A  (body = file)
 * (load/push-restpp.mjs is the simpler path for demo-sized snapshots.)
 *
 * The embeddings statement needs TigerGraph 4.2+ (vector attributes).
 */
USE GRAPH JAAL

CREATE LOADING JOB load_jaal FOR GRAPH JAAL {`);

for (const vtype of Object.keys(VERTEX_TYPES)) L.push(`  DEFINE FILENAME v_${vtype};`);
for (const etype of Object.keys(EDGE_TYPES)) L.push(`  DEFINE FILENAME e_${etype};`);
L.push('  DEFINE FILENAME embeddings;', '');

const USING = 'USING SEPARATOR="\\t", HEADER="true", EOL="\\n"';

for (const [vtype, def] of Object.entries(VERTEX_TYPES)) {
  const vals = ['$"id"', ...COMMON.map((c) => `$"${c}"`), '_', '_', ...def.extras.map((c) => `$"${c}"`)];
  L.push(`  LOAD v_${vtype} TO VERTEX ${vtype} VALUES (${vals.join(', ')})`);
  L.push(`    ${USING};`);
}
L.push('');
for (const [etype, def] of Object.entries(EDGE_TYPES)) {
  const extra = (def.extras || []).map((c) => `, $"${c}"`).join('');
  for (const [f, t] of def.pairs) {
    const where = def.pairs.length > 1 ? `\n    WHERE $"from_type" == "${f}" AND $"to_type" == "${t}"` : '';
    L.push(`  LOAD e_${etype} TO EDGE ${etype} VALUES ($"from_id" ${f}, $"to_id" ${t}, $"ts", $"weight", $"weight"${extra})${where}`);
    L.push(`    ${USING};`);
  }
}
L.push('');
L.push('  // TigerVector (4.2+): id <TAB> comma-separated 256 floats, no header');
L.push('  LOAD embeddings TO VECTOR ATTRIBUTE embedding ON VERTEX MessageText VALUES ($0, SPLIT($1, ","))');
L.push('    USING SEPARATOR="\\t", HEADER="false", EOL="\\n";');
L.push('}');
console.log(L.join('\n'));
